styles:
.rog-article-wrapper {
            background-color: #000000;
            color: #FFFFFF;
            font-family: 'Roboto Condensed', sans-serif;
            line-height: 1.6;
            width: 100%;
            box-sizing: border-box;
            padding: 20px;
            overflow: hidden;
        }
        .rog-article-wrapper h2 {
            color: #FFFFFF !important;
            font-family: 'Roboto Condensed', sans-serif !important;
            text-transform: uppercase;
            font-weight: 700;
            font-size: 1.8em;
            margin-top: 40px;
            margin-bottom: 20px;
            border-left: 5px solid #cc0000;
            padding-left: 15px;
            line-height: 1.2;
        }
        .rog-article-wrapper p {
            color: #FFFFFF !important;
            margin-bottom: 20px;
            font-size: 1.1em;
        }
        .rog-article-wrapper a {
            color: #ff3333 !important;
            text-decoration: none;
            font-weight: bold;
            transition: color 0.2s;
        }
        .rog-article-wrapper a:hover {
            color: #ff0000 !important;
            text-decoration: underline;
        }
        /* Style cho Ảnh để không bị vỡ khung */
        .rog-article-wrapper img {
            max-width: 100% !important;
            height: auto !important;
            display: block;
            margin: 25px auto;
            border-radius: 4px;
        }
        .rog-article-wrapper em {
            color: #aaaaaa;
            font-size: 0.9em;
            display: block;
            text-align: center;
            margin-top: -15px;
            margin-bottom: 25px;
        }
